     1	import { writeFile, readFile, runFFmpeg, deleteFile, initFFmpeg } from '../ffmpeg/engine.js';
     2	import { slackEmojiCmds } from '../ffmpeg/commands.js';
     3	
     4	const TARGET_SIZE = 128 * 1024; // 128 KB
     5	
     6	const COLOR_STEPS = [256, 128, 64, 32];
     7	const FPS_STEPS = [20, 15, 10, 8, 5];
     8	const SIZE_STEPS = [128, 96, 64];
     9	
    10	/**
    11	 * Iteratively compress a GIF to fit Slack emoji requirements:
    12	 * square, ≤128KB. Tries progressively more aggressive settings.
    13	 */
    14	export async function slackEmojiExport(gifData) {
    15	  await initFFmpeg();
    16	
    17	  for (const size of SIZE_STEPS) {
    18	    for (const colors of COLOR_STEPS) {
    19	      for (const fps of FPS_STEPS) {
    20	        const result = await runTwoPass(gifData, { size, colors, fps });
    21	        if (result.byteLength <= TARGET_SIZE) {
    22	          return result;
    23	        }
    24	      }
    25	    }
    26	  }
    27	
    28	  // Return the most aggressively compressed version even if over target
    29	  const lastSize = SIZE_STEPS[SIZE_STEPS.length - 1];
    30	  const lastColors = COLOR_STEPS[COLOR_STEPS.length - 1];
    31	  const lastFps = FPS_STEPS[FPS_STEPS.length - 1];
    32	  return await runTwoPass(gifData, { size: lastSize, colors: lastColors, fps: lastFps });
    33	}
    34	
    35	async function runTwoPass(gifData, opts) {
    36	  await writeFile('input.gif', gifData);
    37	  const [pass1, pass2] = slackEmojiCmds('input.gif', 'output.gif', opts);
    38	  await runFFmpeg(pass1);
    39	  await runFFmpeg(pass2);
    40	  const result = await readFile('output.gif');
    41	  await deleteFile('input.gif');
    42	  await deleteFile('output.gif');
    43	  await deleteFile('palette.png');
    44	  return result;
    45	}
