851	     9	  }
852	    10	
853	    11	  const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
854	    12	  const width = view.getUint16(6, true);
855	    13	  const height = view.getUint16(8, true);
856	    14	
857	    15	  let frames = 0;
858	    16	  let totalDelay = 0;
859	    17	  const delays = [];
860	    18	
861	    19	  // Skip header (13 bytes) + global color table
862	    20	  const packed = data[10];
863	    21	  const hasGCT = (packed >> 7) & 1;
864	    22	  const gctSize = hasGCT ? 3 * (1 << ((packed & 0x07) + 1)) : 0;
865	    23	  let offset = 13 + gctSize;
866	    24	
867	    25	  try {
868	    26	    while (offset < data.length - 1) {
