875	    33	        const label = data[offset + 1];
876	    34	        if (label === 0xf9 && offset + 7 < data.length) {
877	    35	          // graphic control extension
878	    36	          const delay = view.getUint16(offset + 4, true) * 10; // centiseconds -> ms
879	    37	          delays.push(delay || 100); // default 100ms if 0
880	    38	          totalDelay += delay || 100;
881	    39	          offset += 8; // fixed size block
882	    40	        } else {
883	    41	          // skip other extensions
884	    42	          offset += 2;
885	    43	          while (offset < data.length) {
886	    44	            const sz = data[offset];
887	    45	            if (sz === 0) { offset++; break; }
888	    46	            offset += sz + 1;
889	    47	          }
890	    48	        }
891	    49	      } else if (block === 0x2c) {
