     1	/** Lightweight pub/sub state store */
     2	
     3	const MAX_UNDO_OPERATIONS = 20;
     4	const CHECKPOINT_CACHE_SIZE = 3;
     5	
     6	const initialState = {
     7	  /** @type {Uint8Array|null} original GIF bytes (never mutated) */
     8	  originalGif: null,
     9	  /** @type {Uint8Array|null} current GIF bytes after edits */
    10	  currentGif: null,
    11	  /** @type {string|null} object URL for preview */
    12	  previewUrl: null,
    13	  /** GIF metadata */
    14	  meta: { width: 0, height: 0, frames: 0, duration: 0, size: 0 },
    15	  /** @type {Array<{tool: string, params: object}>} operation history for undo */
    16	  operations: [],
    17	  /** @type {Map<number, Uint8Array>} blob checkpoints keyed by operation index */
    18	  checkpoints: new Map(),
    19	  /** @type {string|null} currently active tool */
    20	  activeTool: null,
    21	  /** whether FFmpeg is currently processing */
    22	  processing: false,
    23	  /** whether FFmpeg is loaded */
    24	  ffmpegReady: false,
    25	};
    26	
    27	let state = { ...initialState, checkpoints: new Map() };
    28	const listeners = new Map();
    29	
    30	export function getState() {
    31	  return state;
    32	}
    33	
    34	export function setState(partial) {
    35	  const prev = { ...state };
    36	  Object.assign(state, partial);
    37	
    38	  for (const [key, cbs] of listeners) {
    39	    if (key in partial) {
    40	      for (const cb of cbs) cb(state[key], prev[key]);
    41	    }
    42	  }
    43	  // wildcard listeners
    44	  if (listeners.has('*')) {
    45	    for (const cb of listeners.get('*')) cb(state, prev);
    46	  }
    47	}
    48	
    49	export function subscribe(key, cb) {
    50	  if (!listeners.has(key)) listeners.set(key, new Set());
    51	  listeners.get(key).add(cb);
    52	  return () => listeners.get(key).delete(cb);
    53	}
    54	
    55	export function revokePreview() {
    56	  if (state.previewUrl) {
    57	    URL.revokeObjectURL(state.previewUrl);
    58	    setState({ previewUrl: null });
    59	  }
    60	}
    61	
    62	export function setPreviewFromGif(gifBytes) {
    63	  revokePreview();
    64	  const blob = new Blob([gifBytes], { type: 'image/gif' });
    65	  setState({ previewUrl: URL.createObjectURL(blob) });
    66	}
    67	
    68	/** Push an operation to the undo stack */
    69	export function pushOperation(tool, params, resultGif) {
    70	  const ops = [...state.operations, { tool, params }];
    71	  if (ops.length > MAX_UNDO_OPERATIONS) {
    72	    ops.shift();
    73	    // shift checkpoints too
    74	    const newCheckpoints = new Map();
    75	    for (const [idx, data] of state.checkpoints) {
    76	      if (idx > 0) newCheckpoints.set(idx - 1, data);
    77	    }
    78	    state.checkpoints = newCheckpoints;
    79	  }
    80	
    81	  // Cache checkpoint every few operations for faster undo
    82	  const checkpoints = new Map(state.checkpoints);
    83	  if (ops.length % Math.ceil(MAX_UNDO_OPERATIONS / CHECKPOINT_CACHE_SIZE) === 0) {
    84	    // Keep only CHECKPOINT_CACHE_SIZE most recent
    85	    if (checkpoints.size >= CHECKPOINT_CACHE_SIZE) {
    86	      const oldest = Math.min(...checkpoints.keys());
    87	      checkpoints.delete(oldest);
    88	    }
    89	    checkpoints.set(ops.length - 1, resultGif);
    90	  }
    91	
    92	  setState({ operations: ops, currentGif: resultGif, checkpoints });
    93	  setPreviewFromGif(resultGif);
    94	}
    95	
    96	/** Pop the last operation (undo) */
    97	export function popOperation() {
    98	  if (state.operations.length === 0) return null;
    99	  const ops = state.operations.slice(0, -1);
   100	  setState({ operations: ops });
   101	  return ops;
   102	}
   103	
   104	export function resetState() {
   105	  revokePreview();
   106	  state = { ...initialState, checkpoints: new Map() };
   107	}
