    69	async function fetchWithProgress(url, cacheKey) {
    70	  // Check IndexedDB cache first
    71	  const cached = await getCached(cacheKey);
    72	  if (cached?.version === CORE_VERSION && cached?.data) {
    73	    console.log('[FFmpeg] Loaded WASM from IndexedDB cache');
    74	    return URL.createObjectURL(new Blob([cached.data], { type: 'application/wasm' }));
    75	  }
    76	  console.log('[FFmpeg] Cache miss, downloading WASM from', url);
    77	
    78	  const response = await fetch(url);
    79	  const contentLength = Number(response.headers.get('content-length')) || 0;
    80	  const reader = response.body.getReader();
    81	  const chunks = [];
    82	  let received = 0;
    83	
    84	  while (true) {
    85	    const { done, value } = await reader.read();
    86	    if (done) break;
    87	    chunks.push(value);
    88	    received += value.length;
    89	    if (contentLength > 0) {
    90	      const pct = Math.round((received / contentLength) * 100);
    91	      const mb = (received / 1024 / 1024).toFixed(1);
    92	      const totalMb = (contentLength / 1024 / 1024).toFixed(1);
    93	      updateProgress(pct, `Downloading engine… ${mb} / ${totalMb} MB`);
    94	    }
    95	  }
    96	
    97	  const data = new Uint8Array(received);
    98	  let offset = 0;
    99	  for (const chunk of chunks) {
   100	    data.set(chunk, offset);
   101	    offset += chunk.length;
   102	  }
   103	
   104	  // Store in IndexedDB for next time
   105	  console.log(`[FFmpeg] Download complete: ${(received / 1024 / 1024).toFixed(1)} MB, caching to IndexedDB`);
   106	  await setCached(cacheKey, { version: CORE_VERSION, data });
   107	
   108	  return URL.createObjectURL(new Blob([data], { type: 'application/wasm' }));
   109	}
